import Collection from "./collection.js";
import Document from "./document.js";
import Upload from "./upload.js";
import FsStorage from "../storage/fs.js";
import { normalizePath } from "./utils/path.js";
import { basename, dirname } from "../deps/std.js";
import Git from "./git.js";
import init from "./routes/main.js";
import { Basic } from "../auth/basic.js";
import Action from "./action.js";
import { cwd } from "./services/process.js";
const allowedTypes = ["object", "object-list", "choose"];
const defaults = {
    site: {},
    basePath: "/",
    data: {},
};
export default class Cms {
    fetch;
    options;
    storages = new Map();
    uploads = new Map();
    fields = new Map();
    collections = new Map();
    documents = new Map();
    actions = new Map();
    gitRepo;
    authentication;
    constructor(options) {
        this.options = {
            ...defaults,
            ...options,
        };
        this.options.root = normalizePath(this.options.root ?? cwd());
        // Set the .fetch method (https://github.com/denoland/deno/issues/24062)
        let fetch;
        this.fetch = (request) => {
            if (!fetch) {
                fetch = this.init().fetch;
            }
            return fetch(request);
        };
    }
    /** Setup the Git repository */
    git(options) {
        this.gitRepo = new Git({
            ...options,
        });
        return this;
    }
    /** Setup the auth */
    auth(users, method = "basic") {
        this.options.auth = {
            method,
            users,
        };
        return this;
    }
    /** Add a new storage method */
    storage(name, storage = "") {
        this.storages.set(name, storage);
        return this;
    }
    upload(name, store, publicPath) {
        const options = typeof name === "string"
            ? {
                name,
                store,
                publicPath,
            }
            : name;
        if (!options.description) {
            const [name, description] = options.name.split(":").map((part) => part.trim());
            options.name = name;
            options.description = description;
        }
        if (!options.publicPath) {
            const path = options.store.split(":")[1] ?? "/";
            options.publicPath = normalizePath(path.split("*")[0]);
        }
        this.uploads.set(options.name, options);
        return this;
    }
    action(name, action) {
        const options = typeof name === "string"
            ? {
                name,
                action,
            }
            : name;
        if (!options.description) {
            const [name, description] = options.name.split(":").map((part) => part.trim());
            options.name = name;
            options.description = description;
        }
        this.actions.set(options.name, options);
        return this;
    }
    collection(name, store, fields) {
        const options = typeof name === "string"
            ? {
                name,
                store,
                fields,
            }
            : name;
        if (!options.description) {
            const [name, description] = options.name.split(":").map((part) => part.trim());
            options.name = name;
            options.description = description;
        }
        this.collections.set(options.name, options);
        return this;
    }
    document(name, store, fields) {
        const options = typeof name === "string"
            ? {
                name,
                store,
                fields,
            }
            : name;
        if (!options.description) {
            const [name, description] = options.name.split(":").map((part) => part.trim());
            options.name = name;
            options.description = description;
        }
        this.documents.set(options.name, options);
        return this;
    }
    field(name, field) {
        this.fields.set(name, field);
        return this;
    }
    /** Use a plugin */
    use(plugin) {
        plugin(this);
        return this;
    }
    /** Initialize the CMS content */
    initContent() {
        const content = {
            basePath: this.options.basePath,
            site: this.options.site ?? {},
            data: this.options.data ?? {},
            git: this.gitRepo,
            collections: {},
            documents: {},
            uploads: {},
            actions: {},
        };
        // Initialize actions
        for (const options of this.actions.values()) {
            content.actions[options.name] = new Action(options);
        }
        // Initialize uploads
        for (const options of this.uploads.values()) {
            content.uploads[options.name] = new Upload({
                ...options,
                storage: this.#getStorage(options.store),
            });
        }
        // Initialize collections
        for (const options of this.collections.values()) {
            const { store, fields, type, ...other } = options;
            content.collections[options.name] = new Collection({
                storage: this.#getStorage(store),
                fields: fields ? this.#resolveFields(fields, content, type) : undefined,
                previewUrl: this.options.previewUrl,
                ...other,
            });
        }
        // Initialize documents
        for (const options of this.documents.values()) {
            const { store, fields, type, ...other } = options;
            content.documents[options.name] = new Document({
                entry: this.#getEntry(store),
                fields: fields ? this.#resolveFields(fields, content, type) : undefined,
                previewUrl: this.options.previewUrl,
                ...other,
            });
        }
        return content;
    }
    /** Start the CMS */
    init() {
        // JavaScript files to import
        const jsImports = new Set(this.fields.values().map((field) => field.jsImport));
        const initOptions = {
            content: this.initContent(),
            jsImports: Array.from(jsImports),
            basePath: this.options.basePath,
            extraHead: this.options.extraHead,
            staticFolders: this.options.staticFolders,
            sourcePath: this.options.sourcePath,
            users: new Map(),
        };
        // Authentication method
        const { auth } = this.options;
        let authMethod;
        if (auth) {
            for (const [user, password] of Object.entries(auth.users)) {
                initOptions.users.set(user, typeof password === "string" ? { password } : password);
            }
            authMethod = auth.method === "basic" ? Basic.create() : auth.method;
            authMethod.init(initOptions);
            initOptions.authMethod = authMethod;
        }
        return init(initOptions);
    }
    #getStorage(path) {
        const [name, src] = path.split(":");
        const storage = this.storages.get(name);
        if (storage === undefined) {
            throw new Error(`Unknown storage "${name}"`);
        }
        if (typeof storage === "string") {
            const fs = new FsStorage({ root: this.options.root, path: storage });
            this.storages.set(name, fs);
            return src ? fs.directory(src) : fs;
        }
        return src ? storage.directory(src) : storage;
    }
    #getEntry(path) {
        const [name, src] = path.split(":");
        const storage = this.#getStorage(name + ":" + dirname(src));
        return storage.get(basename(src));
    }
    #resolveFields(fields, content, type = "object") {
        if (!allowedTypes.includes(type)) {
            throw new Error(`Unknown document type "${type}"`);
        }
        const field = this.fields.get(type);
        if (!field) {
            throw new Error(`Field of type "${type}" was not found`);
        }
        return {
            name: "root",
            type: "object",
            tag: field.tag + "-root",
            applyChanges: field.applyChanges,
            init: field.init,
            fields: fields.map((field) => this.#resolveField(field, content)),
        };
    }
    #resolveField(field, content) {
        // deno-lint-ignore no-explicit-any
        let resolvedField;
        if (typeof field === "string") {
            const parts = field.split(":").map((part) => part.trim());
            resolvedField = {
                name: parts[0],
                type: parts[1],
            };
            if (resolvedField.type.endsWith("!")) {
                resolvedField.type = resolvedField.type.slice(0, -1);
                resolvedField.attributes = { required: true };
            }
        }
        else {
            resolvedField = field;
        }
        const type = this.fields.get(resolvedField.type);
        if (!type) {
            throw new Error(`Unknown field of type "${resolvedField.type}"`);
        }
        resolvedField = {
            tag: type.tag,
            label: resolvedField.label ?? resolvedField.name,
            applyChanges: type.applyChanges,
            ...resolvedField,
        };
        if (resolvedField.fields) {
            resolvedField.fields = resolvedField.fields.map((field) => this.#resolveField(field, content));
        }
        if (type.init) {
            const customInit = resolvedField.init;
            resolvedField.init =
                typeof customInit === "function"
                    ? async (field, content, data) => {
                        await type.init(field, content);
                        await customInit(field, content, data);
                    }
                    : type.init;
        }
        return resolvedField;
    }
}
